// One item per PDF attachment. Images (logos, signatures) and other files are ignored.
// Skips any attachment this workflow has already logged, so a re-run never double-logs.
const store = $getWorkflowStaticData('global');
store.files = store.files || {};
const out = [];
for (const email of $('New supplier bill email').all()) {
  const m = email.json;
  const from = (m.from && (m.from.text || (m.from.value && m.from.value[0] && m.from.value[0].address))) || '';
  for (const [key, file] of Object.entries(email.binary || {})) {
    const isPdf = /pdf/i.test(file.mimeType || '') || /\.pdf$/i.test(file.fileName || '');
    if (!isPdf) continue;
    const fileKey = m.id + '|' + (file.fileName || key);
    if (store.files[fileKey]) continue;
    out.push({
      json: { emailId: m.id, fileKey, from, subject: m.subject || '', receivedAt: m.date || '', fileName: file.fileName || key },
      binary: { data: file },
    });
  }
}
return out;

// Keeps the email details next to the PDF text, and decides whether the text is worth sending to the AI.
// A scanned or photographed bill has no text layer, so it goes straight to a human instead of the AI.
const s = $('Settings').first().json;
const minChars = Number(s.minTextChars || 60);
const maxChars = Number(s.maxTextChars || 15000);
const split = $('Split PDF attachments').all();
return $input.all().map((item, i) => {
  const meta = split[i].json;
  const text = String(item.json.text || '').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
  let readProblem = '';
  if (item.json.error) readProblem = 'Could not open the PDF (password-protected or damaged): ' + String(item.json.error).slice(0, 120);
  else if (text.length < minChars) readProblem = 'No readable text in the PDF. It is probably a scan or photo, so enter it by hand';
  const textForAi = readProblem ? '' : `Email from: ${meta.from}\nFile name: ${meta.fileName}\n\n${text.slice(0, maxChars)}`;
  return { json: { ...meta, pages: item.json.numpages || null, textChars: text.length, readProblem, textForAi }, binary: split[i].binary };
});

// Checks every extraction before anything is trusted. Nothing here approves or pays a bill.
// Hard problems -> Status CHECK (a person is emailed). GST observations -> notes only (logged, not blocking).
const s = $('Settings').first().json;
const tz = s.timezone || 'Asia/Singapore';
const gstRate = Number(s.gstRatePercent || 9) / 100;
const tol = Number(s.sumTolerance || 0.02);
const src = $('Prepare text for AI').all();
const store = $getWorkflowStaticData('global');
store.invoices = store.invoices || {};

const day = d => new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(d);             // YYYY-MM-DD
const today = day(new Date());
const clock = new Intl.DateTimeFormat('en-GB', { timeZone: tz, hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date());
const num = v => {
  if (v === undefined || v === null || v === '') return null;
  const n = typeof v === 'number' ? v : Number(String(v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
};
const r2 = n => Math.round(n * 100) / 100;
const f2 = n => Number(n).toLocaleString('en-SG', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const isDate = v => /^\d{4}-\d{2}-\d{2}$/.test(String(v || ''));
const daysBetween = (a, b) => Math.round((new Date(b) - new Date(a)) / 86400000);
const norm = t => String(t || '').toLowerCase().replace(/\b(pte|ltd|limited|private|co|company|inc|llp|sdn|bhd)\b/g, '').replace(/[^a-z0-9]/g, '');
const invKey = (sup, no) => norm(sup) + '|' + String(no || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const seenThisRun = {};

return $input.all().map((item, i) => {
  const meta = src[i].json;
  const ai = item.json.output || {};
  const problems = [], notes = [];

  const supplier = String(ai.supplier_name || '').trim();
  const invNo = String(ai.invoice_number || '').trim();
  const currency = String(ai.currency || '').trim().toUpperCase();
  let subtotal = num(ai.subtotal), gst = num(ai.gst);
  const total = num(ai.total), lines = num(ai.line_count);
  const docType = String(ai.document_type || '').trim().toLowerCase();

  if (meta.readProblem) problems.push(meta.readProblem);
  else if (item.json.error || !item.json.output) problems.push('The AI step could not read this PDF: ' + String(item.json.error || 'no output').slice(0, 160));
  else {
    // 1. Is it a bill at all? Statements, quotations, delivery orders and credit notes need a person.
    if (docType && (!/invoice|bill/.test(docType) || /credit/.test(docType) || /pro.?forma/.test(docType))) problems.push(`This looks like a ${docType}, not a supplier invoice`);
    // 2. Required fields
    if (!supplier) problems.push('Supplier name missing');
    if (!invNo) problems.push('Invoice number missing');
    if (!isDate(ai.invoice_date)) problems.push('Invoice date missing or unreadable');
    if (!/^[A-Z]{3}$/.test(currency)) problems.push('Currency unclear');
    if (total === null) problems.push('Total missing');
    else if (total <= 0) problems.push('Total is zero or negative (credit note?)');
    // 3. The numbers must add up: subtotal + GST = total (within the tolerance in Settings)
    if (subtotal === null && (gst === null || gst === 0) && total !== null) { subtotal = total; gst = 0; }
    if (subtotal !== null && total !== null) {
      const g = gst || 0;
      if (Math.abs(r2(subtotal + g) - total) > tol) problems.push(`Subtotal ${f2(subtotal)} + GST ${f2(g)} = ${f2(r2(subtotal + g))}, but the total reads ${f2(total)}`);
    } else if (subtotal === null && gst) problems.push('GST shown but no subtotal, so the sum cannot be checked');
    // 4. Dates that make sense
    if (isDate(ai.invoice_date)) {
      if (ai.invoice_date > today) problems.push(`Invoice date ${ai.invoice_date} is in the future`);
      else if (daysBetween(ai.invoice_date, today) > 180) notes.push(`Invoice is dated ${ai.invoice_date}, more than 6 months ago`);
      if (isDate(ai.due_date) && ai.due_date < ai.invoice_date) problems.push(`Due date ${ai.due_date} is before the invoice date`);
    }
    // 5. Duplicates: same supplier + same invoice number already logged (or twice in this batch)
    if (supplier && invNo) {
      const k = invKey(supplier, invNo);
      if (store.invoices[k]) problems.push(`Possible duplicate: ${invNo} from this supplier was already logged on ${store.invoices[k]}`);
      else if (seenThisRun[k]) problems.push(`Possible duplicate: ${invNo} from this supplier arrived twice in this batch`);
      seenThisRun[k] = true;
    }
    // 6. GST observations: flagged, never enforced (rates change, some bills are zero-rated or overseas)
    if (gst && subtotal) {
      const expected = r2(subtotal * gstRate);
      const allowance = Math.max(0.10, 0.005 * (lines || 1));
      if (Math.abs(gst - expected) > allowance) notes.push(`GST is ${f2(gst)}; ${s.gstRatePercent || 9}% of the subtotal would be ${f2(expected)}. Check the rate`);
      if (!ai.supplier_gst_reg_no) notes.push('GST charged but no GST registration number found on the bill');
    } else if (!gst && !problems.length) notes.push('No GST on this bill');
  }

  const status = problems.length ? 'CHECK' : (notes.length ? 'OK, see note' : 'OK');
  return {
    json: {
      'Logged on': `${today} ${clock}`,
      'Status': status,
      'Issues': [...problems, ...notes].join('; '),
      'Supplier': supplier,
      'Invoice no.': invNo,
      'Invoice date': isDate(ai.invoice_date) ? ai.invoice_date : '',
      'Due date': isDate(ai.due_date) ? ai.due_date : '',
      'Currency': currency,
      'Subtotal': subtotal === null ? '' : r2(subtotal),
      'GST': gst === null ? '' : r2(gst),
      'Total': total === null ? '' : r2(total),
      'Lines': lines === null ? '' : lines,
      'Document': docType,
      'From': meta.from,
      'Email subject': meta.subject,
      'File': meta.fileName,
      'Email ID': meta.emailId,
    },
    binary: src[i].binary,
  };
});

// Records what was logged: each attachment (so a re-run skips it) and each supplier + invoice number
// (so a resent or duplicate bill is caught next time). Passes the items on unchanged.
const store = $getWorkflowStaticData('global');
store.files = store.files || {};
store.invoices = store.invoices || {};
const today = new Intl.DateTimeFormat('en-CA', { timeZone: $('Settings').first().json.timezone || 'Asia/Singapore' }).format(new Date());
const norm = t => String(t || '').toLowerCase().replace(/\b(pte|ltd|limited|private|co|company|inc|llp|sdn|bhd)\b/g, '').replace(/[^a-z0-9]/g, '');
const invKey = (sup, no) => norm(sup) + '|' + String(no || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
for (const item of $input.all()) {
  const r = item.json;
  store.files[r['Email ID'] + '|' + r['File']] = today;
  if (r['Supplier'] && r['Invoice no.'] && !store.invoices[invKey(r['Supplier'], r['Invoice no.'])]) store.invoices[invKey(r['Supplier'], r['Invoice no.'])] = today;
}
// Housekeeping: forget attachments after 90 days and invoice numbers after 2 years
const age = d => (Date.now() - new Date(d)) / 86400000;
for (const [k, d] of Object.entries(store.files)) if (age(d) > 90) delete store.files[k];
for (const [k, d] of Object.entries(store.invoices)) if (age(d) > 730) delete store.invoices[k];
return $input.all();

// One email per bill that needs a person, with the PDF attached and the reasons spelled out.
const s = $('Settings').first().json;
const r = $json;
const who = r['Supplier'] || r['File'];
const val = (label, v) => `${label}: ${v === '' || v === undefined || v === null ? '(not found)' : v}`;
const body = [
  `This supplier bill was logged in the "${s.sheetName}" sheet with status CHECK. Please look at it before it goes any further.`,
  '',
  'Why it was flagged:',
  ...String(r['Issues']).split('; ').map(x => '- ' + x),
  '',
  'What the AI read from the PDF:',
  val('Supplier', r['Supplier']), val('Invoice no.', r['Invoice no.']), val('Invoice date', r['Invoice date']),
  val('Due date', r['Due date']), val('Currency', r['Currency']), val('Subtotal', r['Subtotal']), val('GST', r['GST']), val('Total', r['Total']),
  '',
  `Email: "${r['Email subject']}" from ${r['From']}`,
  `File: ${r['File']} (attached)`,
  '',
  'Correct the row in the sheet, or enter the bill by hand. Nothing has been sent to Xero and nothing has been paid.',
].join('\n');
return {
  json: { to: s.reviewerEmail, subject: `Check this supplier bill: ${who}${r['Invoice no.'] ? ' ' + r['Invoice no.'] : ''}`, body },
  binary: $input.item.binary,
};
